#include <cstdint>
#include <string>
#include <utility>
#include <vector>

std::uint32_t missingRights(std::uint32_t requested, std::uint32_t granted)
{
    return requested & ~granted;
}

std::vector<std::string> rightNames(std::uint32_t mask)
{
    static const std::pair<std::uint32_t, const char*> table[]{
        { 0x0001, "terminate" }, { 0x0002, "create_thread" }, { 0x0008, "vm_operation" }, { 0x0010, "vm_read" },
        { 0x0020, "vm_write" }, { 0x0400, "query_information" }, { 0x1000, "query_limited_information" }, { 0x100000, "synchronize" },
    };
    std::vector<std::string> names;
    std::uint32_t known{ 0 };
    for (const auto& [bit, name] : table)
    {
        known |= bit;
        if (mask & bit) names.push_back(name);
    }
    if (mask & ~known) names.push_back("other");
    return names;
}

unitTests:
using N = std::vector<std::string>;
TEST("missing read") { CHECK_EQ(missingRights(0x1010, 0x1000), 0x0010u); }
TEST("nothing missing") { CHECK_EQ(missingRights(0x1000, 0x101000), 0u); }
TEST("everything missing") { CHECK_EQ(missingRights(0x0021, 0), 0x0021u); }
TEST("names in table order") { CHECK(rightNames(0x1010) == N({ "vm_read", "query_limited_information" })); }
TEST("synchronize and terminate") { CHECK(rightNames(0x100001) == N({ "terminate", "synchronize" })); }
TEST("unknown bits") { CHECK(rightNames(0x0004) == N({ "other" })); CHECK(rightNames(0x80000010) == N({ "vm_read", "other" })); }
TEST("no rights") { CHECK(rightNames(0).empty()); }

